  // ── src/render-walls.js ──

  // ── render-walls: the light table, the cells of a frame, one ray per column (walls, doors, jambs), floor and ceiling ──

  var CDA_PROJ = (CDA_W / 2) / Math.tan(CDA_FOV / 2);
