    var noise = ctx.createBuffer(1, rate, rate);
    var data = noise.getChannelData(0);
    for (var i = 0; i < data.length; i++) data[i] = cdaRand(CDA_SFX) * 2 - 1;
    CDA_SFX.master = master;
